import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let b = string.floatBits(1.0)
    io.println("b ${b}")
    let n = string.floatBits(2.5)
    io.println("n ${n}")
    let g = string.floatFromBits(n)
    io.println("g ${g}")
    if string.floatFromBits(string.floatBits(0.25)) == 0.25 { io.println("rt-ok") } else { io.println("rt-bad") }
    return Ok(())
}
